};

int main() {
    Base* basePtr = new Derived();
    basePtr->Void();
    delete basePtr;
    return 0;
}
```

### Solution:
```cpp
#include <iostream>

class Base {
public:
    virtual void Void() {
        std::cout << "Base::Void()" << std::endl;
    }
};

class Derived : public Base {
public:
    void Void() override {
        std::cout << "Derived::Void()" << std::endl;
    }
};

int main() {
    Base* basePtr = new Derived();
    basePtr->Void();  // Output: Derived::Void()
    delete basePtr;
    return 0;
}
