class CustomParser:
    def __init__(self, parser, parent:ParserRuleContext=None, invokingState:int=-1):
        super().__init__(parent, invokingState)
        self.parser = parser

    def TYPE(self):
        return self.getToken(jsgParser.TYPE, 0)

    def name(self):
        return self.getTypedRuleContext(jsgParser.NameContext,0)

    def process_variable_declaration(self, input_code):
        # Split the input code by spaces to separate the type and variable name
        tokens = input_code.split()

