import random

class RandomCharacter:
    def select_character(self, alphabet):
        return random.choice(alphabet)

class LowercaseCharacter(RandomCharacter):
    def select_character(self, alphabet):
        return super().select_character(alphabet.lower())

class UppercaseCharacter(RandomCharacter):
    def select_character(self, alphabet):
        return super().select_character(alphabet.upper())

